const {equal} = require('node:assert').strict;
const test = require('node:test');
const {throws} = require('node:assert').strict;

const {decodePsbt} = require('./../../');
const {extractTransaction} = require('./../../');

// Test scenarios
const tests = {
  a_psbt_without_final_scripts_cannot_be_extracted: {
    args: {psbt: '70736274ff01003f0200000001ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff0000000000ffffffff010000000000000000036a01aa000000000009f00102030405060708100f0102030405060708090a0b0c0d0e0f0000'},
    err: 'ExpectedFinalScriptSigsAndWitnesses',
    msg: 'A psbt without final scripts cannot be extracted',
  },
  a_final_scriptwitness_is_split_by_element_lengths: {
    args: {
      psbt: '',
    },
    msg: 'A final scriptwitness is split into elements by their lengths',
    result: {
      transaction: '',
    },
  },
  a_final_scriptwitness_that_is_not_a_witness_stack_is_rejected: {
    args: {
      psbt: '70736274ff01003f0200000001ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff0000000000ffffffff010000000000000000036a01aa0000000000010804005101aa0000',
    },
    err: 'InvalidScriptWitness',
    msg: 'A final scriptwitness that is not a valid witness stack is rejected',
  },
  an_invalid_psbt_is_rejected: {
    args: {psbt: '00'},
    err: 'UnrecognizedMagicBytes',
    msg: 'An invalid psbt is rejected when extracting a transaction',
  },
   a_transaction_extractor_extracts_a_transaction: {
    args: {
      psbt: '',
    },
    msg: 'A transaction extractor must create a transaction',
    result: {
      transaction: '',
    },
  },
  an_empty_final_scriptsig_is_extracted: {
    args: {
      psbt: '70736274ff01003d020000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff01e803000000000000016a00000000000107000000',
    },
    msg: 'An input with an explicitly empty final scriptsig is extracted',
    result: {
      transaction: '020000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff01e803000000000000016a00000000',
    },
  },
  a_transaction_without_inputs_cannot_be_extracted: {
    args: {
      psbt: '70736274ff010014020000000001e803000000000000016a000000000000',
    },
    err: 'ExpectedInputsToExtractTransaction',
    msg: 'A transaction without inputs cannot be extracted',
  },
  a_transaction_without_outputs_cannot_be_extracted: {
    args: {
      psbt: '70736274ff010033020000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff0000000000000107015100',
    },
    err: 'ExpectedOutputsToExtractTransaction',
    msg: 'A transaction without outputs cannot be extracted',
  },
  a_witness_of_one_empty_element_is_extracted_as_a_witness: {
    args: {
      psbt: '70736274ff01003d020000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff01e803000000000000016a000000000001080201000000',
    },
    msg: 'A witness of one empty element uses the witness serialization',
    result: {
      transaction: '0200000000010111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff01e803000000000000016a010000000000',
    },
  },
  an_empty_final_script_witness_is_extracted: {
    args: {
      psbt: '70736274ff01003d020000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff01e803000000000000016a0000000000010801000000',
    },
    msg: 'An input with an explicitly empty final script witness is extracted',
    result: {
      transaction: '020000000111111111111111111111111111111111111111111111111111111111111111110000000000ffffffff01e803000000000000016a00000000',
    },
  },
};

// Run the tests
Object.keys(tests).map(t => tests[t]).forEach(({args, err, msg, result}) => {
  return test(msg, () => {
    if (!!err) {
      throws(() => extractTransaction(args), new Error(err));

      return;
    }

    const {transaction} = extractTransaction(args);

    equal(transaction, result.transaction);

    return;
  });
});
